//! cb-seat-profile (D-063, main-agent.md §3.4.2): a launch with no configured
//! skills materializes exactly the recipe it did before the launch snapshot
//! existed, on every carrier the Node registers.
//!
//! The fixtures under `tests/fixtures/launch_unchanged/` were generated by
//! this same test on origin/main before cb-seat-profile (set
//! `REMUDA_WRITE_LAUNCH_FIXTURES=<dir>` to regenerate). Paths are normalized
//! to `<root>`, the launch id to `<launch>`, and a materialized file whose
//! bytes name the root is digested with the root replaced, so the fixture
//! does not depend on where the test runs.

use remuda_driver::launch::remuda_skill::SkillContext;
use remuda_driver::{
    BinarySource, Delegation, LaunchOrigin, MaterializeRequest, ProviderHealth, ProviderKind,
    ProviderProfile, SessionAction, hash_file, materialize,
};
use remuda_protocol::{AgentKind, DriverKind, Id, InstanceSpec};
use serde_json::Value;
use std::fs;
use std::path::Path;

const CARRIERS: &[(DriverKind, AgentKind)] = &[
    (DriverKind::ClaudePrint, AgentKind::Claude),
    (DriverKind::ClaudeSdk, AgentKind::Claude),
    (DriverKind::ClaudePty, AgentKind::Claude),
    (DriverKind::ClaudeBg, AgentKind::Claude),
    (DriverKind::GenericPty, AgentKind::Claude),
    (DriverKind::GenericPty, AgentKind::Codex),
    (DriverKind::GenericPty, AgentKind::Grok),
    (DriverKind::GenericPty, AgentKind::Agy),
    (DriverKind::ShellPty, AgentKind::Claude),
    (DriverKind::ShellPty, AgentKind::Codex),
    (DriverKind::ShellPty, AgentKind::Grok),
    (DriverKind::ShellPty, AgentKind::Agy),
];

fn wire(value: impl serde::Serialize) -> String {
    serde_json::to_value(value)
        .unwrap()
        .as_str()
        .unwrap()
        .to_owned()
}

/// Replace `root` everywhere in a JSON value.
fn normalize(value: &mut Value, root: &str) {
    match value {
        Value::String(text) => *text = text.replace(root, "<root>"),
        Value::Array(items) => items.iter_mut().for_each(|item| normalize(item, root)),
        Value::Object(map) => map.values_mut().for_each(|item| normalize(item, root)),
        _ => {}
    }
}

fn recipe_for(driver: DriverKind, kind: AgentKind, managed: bool) -> Value {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    let instance = root.join("instances").join("ins_x");
    let launch = instance.join("launch");
    let home = instance.join("native-home");
    fs::create_dir_all(&launch).unwrap();
    fs::create_dir_all(&home).unwrap();
    let binary = root.join("agent");
    fs::write(&binary, "#!/bin/sh\n").unwrap();
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        fs::set_permissions(&binary, fs::Permissions::from_mode(0o755)).unwrap();
    }
    let mut spec: InstanceSpec =
        serde_json::from_str(include_str!("fixtures/instance-spec.json")).unwrap();
    spec.driver = driver;
    spec.kind = kind;
    spec.cwd = root.to_string_lossy().into_owned();
    let profile = ProviderProfile {
        id: "pvp_01993ab0-0000-7000-8000-000000000001".parse().unwrap(),
        kind: ProviderKind::Anthropic,
        base_url: String::new(),
        delegation: Delegation::None,
        secret_ref: None,
        models: vec!["sonnet".into()],
        health: ProviderHealth::Healthy,
    };
    let context = SkillContext {
        grants: vec!["dispatch".to_owned()],
        herdr: true,
        delegated_decisions: false,
        inbox: false,
        ..Default::default()
    };
    let recipe = materialize(&MaterializeRequest {
        creator: remuda_driver::CreatorControl::default(),
        spec: &spec,
        profile: &profile,
        launch_dir: launch.clone(),
        native_home: home.clone(),
        session: SessionAction::New {
            session_id: "01993ab0-0000-7000-8000-000000000003".to_owned(),
        },
        launch_id: Id::new("launch").unwrap(),
        binary: BinarySource::Pinned(remuda_driver::BinaryPin {
            abs_path: binary.to_string_lossy().into_owned(),
            version: "2.1.291 (Claude Code)".into(),
            sha256: hash_file(&binary).unwrap(),
        }),
        setting_sources: None,
        origin: LaunchOrigin::Human,
        native_home_managed: Some(managed),
        settings_overlay_path: None,
        secret_policy: None,
        memory_context: None,
        skill_context: Some(&context),
        configured_skills: &[],
    })
    .unwrap_or_else(|error| panic!("{driver:?}/{kind:?}: {error}"));
    let root_text = root.to_string_lossy().into_owned();
    let mut value = serde_json::to_value(&recipe).unwrap();
    // A file whose bytes name the root: digest the normalized bytes.
    if let Some(files) = value
        .get_mut("materializedFiles")
        .and_then(Value::as_array_mut)
    {
        for file in files {
            let path = file["path"].as_str().unwrap().to_owned();
            if let Ok(bytes) = fs::read(&path) {
                let text = String::from_utf8_lossy(&bytes);
                if text.contains(&root_text) {
                    let normalized = text.replace(&root_text, "<root>");
                    let scratch = root.join("normalized");
                    fs::write(&scratch, normalized.as_bytes()).unwrap();
                    file["contentDigest"] = Value::String(hash_file(&scratch).unwrap().into());
                }
            }
        }
    }
    value["launchId"] = Value::String("<launch>".into());
    normalize(&mut value, &root_text);
    value
}

fn fixture_name(driver: DriverKind, kind: AgentKind, managed: bool) -> String {
    let home = if managed { "managed" } else { "operator" };
    format!("{}-{}-{home}.json", wire(driver), wire(kind))
}

#[test]
fn a_launch_without_configured_skills_materializes_the_recipe_it_did_before() {
    let fixtures = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/launch_unchanged");
    let write = std::env::var_os("REMUDA_WRITE_LAUNCH_FIXTURES");
    let mut checked = 0;
    for &(driver, kind) in CARRIERS {
        for managed in [true, false] {
            // generic-pty never runs on the inherited operator home.
            if !managed && driver == DriverKind::GenericPty {
                continue;
            }
            let value = recipe_for(driver, kind, managed);
            let name = fixture_name(driver, kind, managed);
            let text = format!("{}\n", serde_json::to_string_pretty(&value).unwrap());
            if let Some(dir) = &write {
                fs::create_dir_all(dir).unwrap();
                fs::write(Path::new(dir).join(&name), text).unwrap();
                continue;
            }
            let expected = fs::read_to_string(fixtures.join(&name))
                .unwrap_or_else(|error| panic!("fixture {name}: {error}"));
            assert_eq!(text, expected, "{name}: the recipe changed");
            checked += 1;
        }
    }
    if write.is_none() {
        assert_eq!(checked, 20, "every carrier and home has a fixture");
    }
}
